  <product_type>Electrical Appliances ; Other Electrical Appliances ; Battery</product_type>
  <product_name>Battery</product_name>
  <product_desc>Brand name: QualiSports, Certification number: XU102405-23012A</product_desc>
  <product_code>
    <publication>2024-05-01</publication>
    <brick>10000546</brick>
